'use strict';
const DAYS=['Monday','Thursday','Saturday'], WEEKDAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const DEFAULT_SCHEDULE=[
{id:'mon-gym',day:'Monday',time:'Flexible',name:'Lower-body strength + acceleration',type:'workout'},
{id:'tue-pitch',day:'Tuesday',time:'4:30 PM',name:'Pitching with Coach Taylor',type:'baseball'},
{id:'wed-practice',day:'Wednesday',time:'7:15 PM',name:'Team practice',type:'baseball'},
{id:'thu-gym',day:'Thursday',time:'Before 7:00 PM',name:'Upper-body strength + stability',type:'workout'},
{id:'thu-hit',day:'Thursday',time:'7:00 PM',name:'Hitting with Dan Kennon',type:'baseball'},
{id:'fri-recover',day:'Friday',time:'Flexible',name:'Recovery and mobility',type:'recovery'},
{id:'sat-gym',day:'Saturday',time:'Flexible',name:'Total-body strength + agility',type:'workout'},
{id:'sun-practice',day:'Sunday',time:'11:00 AM',name:'Team practice',type:'baseball'}];
const KEY='jr-performance-v1';
const base={sessions:{},tests:{},start:'',notes:{},readiness:{},baseball:{},schedule:DEFAULT_SCHEDULE,settings:{rest:90,autoRest:true,week:1},extraEvents:[]};
let db=structuredClone(base);try{let saved=JSON.parse(localStorage.getItem(KEY)||'{}');db={...db,...saved,settings:{...base.settings,...saved.settings},schedule:Array.isArray(saved.schedule)?saved.schedule:DEFAULT_SCHEDULE};}catch(e){console.warn('Unable to load saved workouts',e)}
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let tab='home',week=Math.max(1,Math.min(12,Number(db.settings.week)||1)),day='Monday',view='athlete',selectedDate=new Date().toISOString().slice(0,10),restRemaining=0,restInterval=null,toastTimer=null,syncTimer=null,authToken=null,authUser=null;
function save(){db.settings.week=week;try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){toast('Storage full. Export a backup.')}if(db.settings.cloudAuto&&authToken){clearTimeout(syncTimer);syncTimer=setTimeout(()=>cloudPush(true),3500)}}
function session(w,d){return db.sessions[`${w}-${d}`]||{}}function ensureSession(w,d){return db.sessions[`${w}-${d}`]??={}}function finished(w,d){return !!session(w,d).finished}
function target(w,e){let [n,r]=[e[2],e[3]];if(['Barbell back squat','Barbell front squat','Barbell strict press'].includes(e[0])){if(w===4)return[2,8];if(w===8)return[2,6];if(w===12)return[2,5];if(w>=9)return[3,e[0]==='Barbell back squat'?5:6];if(w>=5)return[e[0]==='Barbell strict press'?2:3,6]}if([4,8,12].includes(w)&&e[1]!=='Warm-up')n=Math.max(1,Math.ceil(n*.65));return[n,r]}
function phase(w){return[4,8,12].includes(w)?'Recovery / Assessment':w<=3?'Foundation':w<=7?'Development':'Strength & Power'}
function today(){return WEEKDAYS[new Date().getDay()]}
function completedCount(){return Object.values(db.sessions).filter(x=>x.finished).length}
function sessionCompletion(w,d){let done=0,total=0;for(let e of exercises[d]){let [n]=target(w,e);total+=n;done+=(session(w,d).items?.[e[0]]?.sets||[]).slice(0,n).filter(x=>x.done).length}return[done,total]}
function latest(w,d,name){for(let i=w-1;i>=1;i--){let a=session(i,d).items?.[name]?.sets||[];let valid=a.filter(x=>x.done&&Number(x.reps)>0);if(valid.length)return{week:i,sets:valid,s:session(i,d)}}return null}
function best(name,exclude){let b=0;for(let w=1;w<=12;w++)for(let d of DAYS){let sets=session(w,d).items?.[name]?.sets||[];sets.forEach((x,j)=>{if(exclude&&exclude.w===w&&exclude.d===d&&exclude.j===j)return;if(x.done&&Number(x.reps)>0&&Number(x.weight)>b)b=Number(x.weight)})}return b}
function readiness(w,d){return db.readiness[`${w}-${d}`]||{}}
function readinessState(w,d){let r=readiness(w,d);let recentPain=Object.entries(db.baseball).some(([date,entries])=>{let age=(Date.now()-new Date(date+'T12:00:00').getTime())/86400000;return age>=-1&&age<=3&&entries.some(x=>x.pain==='Yes')});if(r.pain==='yes'||recentPain)return{level:'red',label:'Pain reported',message:'Do not train through pain. Skip painful movements and ask a parent/qualified clinician about persistent or throwing-related pain.'};if(r.energy===''||r.energy==null||r.sleep===''||r.sleep==null||r.soreness===''||r.soreness==null)return{level:'unknown',label:'Check in first',message:'A quick check-in helps tailor today’s training.'};if(+r.energy<=2||+r.sleep<=2||+r.soreness>=4)return{level:'yellow',label:'Light session recommended',message:'Reduce load and/or sets, avoid hard sprinting if fatigued, and focus on quality. Modified training counts.'};return{level:'green',label:'Ready to train',message:'Follow the planned workout, keep 2–3 reps in reserve, and adjust if anything hurts.'}}
function suggestion(w,d,name){if(!['Barbell back squat','Barbell front squat','Barbell strict press','Trap bar deadlift','Dumbbell bench press','Barbell front squat'].includes(name))return null;let state=readinessState(w,d);if(state.level==='red')return{tone:'danger',title:'Hold — pain reported',detail:'No weight increase. Skip painful exercises and seek guidance.'};if([4,8,12].includes(w))return{tone:'amber',title:'Recovery week',detail:'Reduce volume and keep the load comfortable; no increase.'};if(state.level==='yellow')return{tone:'amber',title:'Keep it light',detail:'Consider reducing weight by ~5–10% and/or removing a set.'};let prior=latest(w,d,name);if(!prior)return{tone:'neutral',title:'Establish a baseline',detail:'Choose a comfortable, well-controlled working weight.'};let sets=prior.sets;let prevTarget=target(prior.week,exercises[d].find(e=>e[0]===name)||['','Strength',3,8])[1];let loads=sets.map(s=>Number(s.weight)).filter(x=>x>0);if(!loads.length)return{tone:'neutral',title:'Technique first',detail:'Log a working weight to enable suggestions.'};let lastLoad=loads[loads.length-1];let allGood=sets.length>=target(prior.week,exercises[d].find(e=>e[0]===name)||['','Strength',3,8])[0]&&sets.every(s=>Number(s.reps)>=prevTarget)&&prior.s.technique==='good'&&+readiness(prior.week,d).energy>=3&&+readiness(prior.week,d).soreness<=3&&readiness(prior.week,d).pain!=='yes';if(allGood&&state.level==='green'){let increment=name==='Barbell strict press'||name==='Dumbbell bench press'?2.5:5;return{tone:'green',title:`Consider ${lastLoad+increment} lb`,detail:`Last: ${lastLoad} lb. Small optional increase (+${increment} lb) if supervised technique stays excellent. Use available plates.`}}return{tone:'amber',title:`Repeat ~${lastLoad} lb`,detail:'Keep or reduce the load until all target reps are comfortable with good technique.'}}
function toast(msg){let el=$('toast');el.textContent=msg;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),3200)}
function nav(t){tab=t;render();window.scrollTo(0,0)}
function renderHeaderAthlete(){const p=profileData(),name=(p.name||'JR').trim()||'JR',avatar=$('headerAvatar'),label=$('headerAthleteName');if(!avatar||!label)return;label.textContent=name.toUpperCase()+' · ATHLETIC DEVELOPMENT';avatar.replaceChildren();if(p.photo){const img=document.createElement('img');img.src=p.photo;img.alt=name+' profile photo';avatar.appendChild(img)}else{avatar.textContent=name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}}
function render(){let items=[['home','⌂','Home'],['train','▣','Train'],['schedule','▦','Schedule'],['progress','↗','Progress'],['library','▶','Movements'],['profile','◉','Profile']];$('bottomNav').innerHTML=items.map(([id,icon,label])=>`<button class="${tab===id?'active':''}" onclick="nav('${id}')"><span class="ico">${icon}</span>${label}</button>`).join('');renderHeaderAthlete();$('headerDate').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});({home:renderHome,train:renderTrain,schedule:renderSchedule,progress:renderProgress,library:renderLibrary,profile:renderProfile})[tab]();renderTimer()}
function scheduleDay(d){return db.schedule.filter(e=>e.day===d)}
function icon(type){return type==='workout'?'🏋️':type==='baseball'?'⚾':'🧘'}
function eventHTML(e){return `<div class="event"><div class="event-icon">${icon(e.type)}</div><div class="event-body"><b>${esc(e.name)}</b><small>${esc(e.time)} · ${esc(e.day)}</small></div><span class="pill ${e.type==='workout'?'':'gray'}">${e.type==='workout'?'GYM':e.type==='baseball'?'BASEBALL':'REST'}</span></div>`}
function renderHome(){let d=today(),w=week,upcoming=DAYS.find(x=>!finished(w,x))||'Monday',count=completedCount(),pct=Math.round(count/36*100),r=readinessState(w,upcoming);let todays=scheduleDay(d);$('app').innerHTML=`<div class="card hero"><span class="pill"> • ATHLETE MODE</span><h1>LET'S GET<br><span class="accent">BETTER TODAY.</span></h1><p>Week ${w} of 12 · ${phase(w)}</p><div class="progresslabel"><b>12-week journey</b><b>${count}/36 workouts</b></div><div class="bar"><span style="width:${pct}%"></span></div><div class="actionrow" style="margin-top:16px"><button onclick="day='${DAYS.includes(d)?d:upcoming}';nav('train')">▶ ${DAYS.includes(d)?'Start today’s workout':'Open next workout'}</button><button class="secondary" onclick="nav('schedule')">View schedule</button></div></div><div class="grid"><div class="card"><small>TRAINING WEEK</small><div class="metric">${w}<span class="muted">/12</span></div><small>${phase(w)}</small></div><div class="card"><small>WORKOUTS DONE</small><div class="metric">${count}<span class="muted">/36</span></div><small>Consistency counts</small></div></div><div class="two-col" style="margin-top:13px"><div class="card"><div class="row"><h2>Today's lineup</h2><span class="pill gray">${esc(d)}</span></div>${todays.length?todays.map(eventHTML).join(''):'<p>Nothing scheduled today.</p>'}</div><div class="card"><h2>Upcoming workouts</h2>${DAYS.map(x=>`<div class="event"><div class="event-body"><b>${finished(w,x)?'✓':'○'} ${x}</b><small>${x==='Monday'?'Lower body + acceleration':x==='Thursday'?'Upper body + stability':'Total body + agility'}</small></div><button class="small secondary" onclick="day='${x}';nav('train')">Open</button></div>`).join('')}<div class="notice" style="margin-top:12px">Tuesday pitching 4:30 PM · Wednesday practice 7:15 PM · Thursday hitting with Dan Kennon 7 PM · Sunday practice 11 AM.</div></div></div><div class="card"><div class="row"><h2>Readiness snapshot</h2><span class="pill ${r.level==='green'?'green':r.level==='red'?'':'amber'}">${esc(r.label)}</span></div><p>${esc(r.message)}</p><button class="secondary" onclick="day='${upcoming}';nav('train')">Check in for ${upcoming}</button></div>`}
function weekSelector(){return `<label>WEEK<select onchange="week=+this.value;save();render()">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${week===i+1?'selected':''}>Week ${i+1}</option>`).join('')}</select></label>`}
function renderTrain(){let s=session(week,day),r=readiness(week,day),state=readinessState(week,day),[done,total]=sessionCompletion(week,day);$('app').innerHTML=`<div class="card hero"><div class="row">${weekSelector()}<label>WORKOUT DATE<input type="date" value="${esc(s.date||'')}" onchange="setSession('date',this.value)"></label></div><div class="tabrow" style="margin-top:13px">${DAYS.map(d=>`<button class="${day===d?'':'secondary'}" onclick="day='${d}';render()">${d}</button>`).join('')}</div><span class="pill">${phase(week)}</span><h1>${day==='Monday'?'LOWER BODY + SPEED':day==='Thursday'?'UPPER BODY + STABILITY':'TOTAL BODY + AGILITY'}</h1><div class="progresslabel"><small>Sets completed</small><b>${done}/${total}</b></div><div class="bar"><span style="width:${total?done/total*100:0}%"></span></div><div class="actionrow" style="margin-top:13px"><button class="secondary" onclick="startRest(90)">⏱ 90s rest</button><button class="secondary" onclick="startRest(120)">2m rest</button><button class="secondary" onclick="startRest(180)">3m rest</button></div></div><div class="card"><div class="row"><h2>60-second readiness check</h2><span class="pill ${state.level==='green'?'green':state.level==='red'?'':'amber'}">${esc(state.label)}</span></div><div class="grid"><label>Energy (1 low–5 high)<select onchange="setReady('energy',this.value)"><option value="">Choose</option>${[1,2,3,4,5].map(v=>`<option ${String(r.energy)===String(v)?'selected':''}>${v}</option>`).join('')}</select></label><label>Sleep quality (1–5)<select onchange="setReady('sleep',this.value)"><option value="">Choose</option>${[1,2,3,4,5].map(v=>`<option ${String(r.sleep)===String(v)?'selected':''}>${v}</option>`).join('')}</select></label><label>Muscle soreness (0–5)<select onchange="setReady('soreness',this.value)"><option value="">Choose</option>${[0,1,2,3,4,5].map(v=>`<option ${String(r.soreness)===String(v)?'selected':''}>${v}</option>`).join('')}</select></label><label>Any pain (especially arm)?<select onchange="setReady('pain',this.value)"><option value="">Choose</option><option value="no" ${r.pain==='no'?'selected':''}>No</option><option value="yes" ${r.pain==='yes'?'selected':''}>Yes</option></select></label></div><div class="notice ${state.level==='red'?'danger':state.level==='green'?'good':''}" style="margin-top:13px">${esc(state.message)}</div>${day==='Thursday'?'<p class="mini">Hitting with Dan Kennon is at 7 PM. Keep pressing light and avoid arm fatigue.</p>':''}</div>${exercises[day].map((e,i)=>exerciseHTML(e,i)).join('')}<div class="card"><h2>Finish workout</h2><div class="grid"><label>Technique<select onchange="setSession('technique',this.value)"><option value="">Choose</option><option value="good" ${s.technique==='good'?'selected':''}>Controlled / good</option><option value="needs-work" ${s.technique==='needs-work'?'selected':''}>Needs improvement</option></select></label><label>Session effort (1–10)<select onchange="setSession('effort',this.value)"><option value="">Choose</option>${Array.from({length:10},(_,i)=>`<option ${String(s.effort)===String(i+1)?'selected':''}>${i+1}</option>`).join('')}</select></label></div><label style="display:block;margin-top:13px">Notes<textarea placeholder="How did it feel? Baseball workload, modifications, soreness..." oninput="setSession('note',this.value)">${esc(s.note||'')}</textarea></label><button class="wide" style="margin-top:12px" onclick="finishWorkout()">${s.finished?'✓ Completed — tap to undo':'✓ Finish workout'}</button><p class="mini">Modified sessions count. Technique, recovery, and health matter more than increasing weight.</p></div>`}
function exerciseHTML(e,i){let [n,reps]=target(week,e),s=session(week,day).items?.[e[0]]||{},last=latest(week,day,e[0]),sg=suggestion(week,day,e[0]);let prev=last?last.sets.map(x=>`${x.weight||'—'} lb × ${x.reps}`).slice(0,3).join(' / '):'No previous entry';return `<section class="card workout-card"><div class="exercise-head"><div><span class="pill gray">${esc(e[1])}</span><h3>${esc(e[0])}</h3><small>${n} sets × ${reps} ${esc(e[4])}</small></div><button class="small secondary" onclick="openDemo(${i})">▶ Video & form</button></div><p class="mini">${esc(e[5])}</p><p class="mini"><b>Previous:</b> ${esc(prev)}</p>${sg?`<div class="notice ${sg.tone==='danger'?'danger':sg.tone==='green'?'good':''}"><b>${esc(sg.title)}</b><br>${esc(sg.detail)}</div>`:''}<div class="set-head"><span>SET</span><span>WEIGHT (LB)</span><span>REPS / RESULT</span><span>DONE</span></div>${Array.from({length:n},(_,j)=>{let v=s.sets?.[j]||{};return `<div class="set-row ${v.done?'done':''}"><span>${j+1}</span><input type="number" min="0" step="any" inputmode="decimal" aria-label="${esc(e[0])} set ${j+1} weight" placeholder="—" value="${esc(v.weight??'')}" oninput="setValue(${i},${j},'weight',this.value)"><input type="number" min="0" step="any" inputmode="decimal" aria-label="${esc(e[0])} set ${j+1} reps" placeholder="${reps}" value="${esc(v.reps??'')}" oninput="setValue(${i},${j},'reps',this.value)"><button class="${v.done?'checked':''}" aria-label="Mark set ${j+1} ${v.done?'incomplete':'complete'}" onclick="toggleSet(${i},${j})">${v.done?'✓':'○'}</button></div>`}).join('')}<div class="stepper"><button class="small secondary" onclick="adjustLoad(${i},-5)">−5 lb</button><button class="small secondary" onclick="adjustLoad(${i},5)">+5 lb</button><button class="small secondary" onclick="copyPrevious(${i})">↻ Last</button></div></section>`}
function setSession(k,v){ensureSession(week,day)[k]=v;save()}
function setReady(k,v){db.readiness[`${week}-${day}`]??={};db.readiness[`${week}-${day}`][k]=v;save();render()}
function ensureSet(i,j){let e=exercises[day][i][0],s=ensureSession(week,day);s.items??={};s.items[e]??={sets:[]};return s.items[e].sets[j]??={}}
function setValue(i,j,k,v){ensureSet(i,j)[k]=v===''?'':Number(v);save()}
function toggleSet(i,j){let e=exercises[day][i],v=ensureSet(i,j),was=!!v.done,oldBest=best(e[0],{w:week,d:day,j});if(v.reps==null||v.reps==='')v.reps=target(week,e)[1];v.done=!was;save();if(!was&&Number(v.weight)>oldBest&&Number(v.weight)>0&&Number(v.reps)>0)toast(`🏆 NEW PR! ${e[0]} — ${v.weight} lb`);else if(!was)toast('✓ Set saved — keep it up!');if(!was&&db.settings.autoRest)startRest(Number(db.settings.rest)||90);render()}
function adjustLoad(i,delta){let e=exercises[day][i],n=target(week,e)[0],s=ensureSession(week,day);let sets=s.items?.[e[0]]?.sets||[],prev=latest(week,day,e[0]);let load=sets.find(x=>x.weight!==''&&x.weight!=null)?.weight??prev?.sets.find(x=>x.weight!==''&&x.weight!=null)?.weight??0;load=Math.max(0,Number(load)+delta);for(let j=0;j<n;j++){let v=ensureSet(i,j);if(!v.done)v.weight=load}save();render()}
function copyPrevious(i){let e=exercises[day][i],prev=latest(week,day,e[0]);if(!prev){toast('No earlier set data yet');return}let n=target(week,e)[0];for(let j=0;j<n;j++){let v=ensureSet(i,j),a=prev.sets[j]||prev.sets[prev.sets.length-1];if(!v.done&&a){v.weight=a.weight??'';v.reps=a.reps??''}}save();render();toast('Previous values copied')}
function finishWorkout(){let s=ensureSession(week,day);if(!s.finished&&readinessState(week,day).level==='red'&&!confirm('Pain was reported. Do not train through pain. Mark this as a modified/recovery session?'))return;s.finished=!s.finished;save();render();toast(s.finished?'🏅 Workout logged! Consistency wins.':'Workout reopened')}
function openDemo(i){showExerciseVideo(exercises[day][i][0])}
function startRest(sec){clearInterval(restInterval);restRemaining=sec;renderTimer();restInterval=setInterval(()=>{restRemaining--;renderTimer();if(restRemaining<=0){clearInterval(restInterval);toast('⏱ Rest complete');if(navigator.vibrate)navigator.vibrate([150,90,150])}},1000)}
function stopRest(){clearInterval(restInterval);restRemaining=0;renderTimer()}
function renderTimer(){let el=$('timerDock');if(restRemaining<=0){el.classList.add('hidden');return}el.classList.remove('hidden');el.innerHTML=`<div class="row"><div><small>REST TIMER</small><br><strong>${Math.floor(restRemaining/60)}:${String(restRemaining%60).padStart(2,'0')}</strong></div><div class="actionrow"><button class="small secondary" onclick="restRemaining+=30;renderTimer()">+30s</button><button class="small" onclick="stopRest()">Done</button></div></div>`}
function calendarGrid(dateStr){let dt=new Date(dateStr+'T12:00:00'),year=dt.getFullYear(),month=dt.getMonth(),first=new Date(year,month,1).getDay(),last=new Date(year,month+1,0).getDate();let html='<div class="row"><button class="small secondary" onclick="moveMonth(-1)">‹</button><b>'+dt.toLocaleDateString(undefined,{month:'long',year:'numeric'})+'</b><button class="small secondary" onclick="moveMonth(1)">›</button></div><div class="calendar-grid">';html+=['S','M','T','W','T','F','S'].map(d=>'<small>'+d+'</small>').join('');for(let i=0;i<first;i++)html+='<span></span>';for(let n=1;n<=last;n++){let date=year+'-'+String(month+1).padStart(2,'0')+'-'+String(n).padStart(2,'0'),weekday=WEEKDAYS[new Date(date+'T12:00:00').getDay()],has=db.schedule.some(e=>e.day===weekday)||db.extraEvents.some(e=>e.date===date),selected=date===dateStr;html+='<button class="cal-day '+(selected?'chosen':'')+'" onclick="selectedDate=\''+date+'\';render()">'+n+(has?'<i>•</i>':'')+'</button>'}return html+'</div>'}
function moveMonth(n){let dt=new Date(selectedDate+'T12:00:00');dt.setDate(1);dt.setMonth(dt.getMonth()+n);selectedDate=dt.toISOString().slice(0,10);render()}
function renderSchedule(){let schedule=db.schedule;let d=selectedDate;let weekday=WEEKDAYS[new Date(d+'T12:00:00').getDay()];let extra=db.extraEvents.filter(x=>x.date===d);$('app').innerHTML=`<div class="card hero"><span class="pill">BASEBALL + TRAINING</span><h1>YOUR <span class="accent">SCHEDULE</span></h1><p>Everything in one place. Record pitching and hitting workload to inform recovery.</p><label>Choose a date<input type="date" value="${esc(d)}" onchange="selectedDate=this.value;render()"></label></div><div class="card">${calendarGrid(d)}</div><div class="card"><h2>${esc(weekday)} · ${esc(d)}</h2>${scheduleDay(weekday).map(eventHTML).join('')||'<p>No repeating activities.</p>'}${extra.map(x=>`<div class="event"><div class="event-body"><b>${esc(x.name)}</b><small>${esc(x.time)}</small></div><button class="small secondary" onclick="removeEvent('${esc(x.id)}')">Remove</button></div>`).join('')}<hr class="divider"><h3>Add a one-time activity</h3><div class="grid"><label>Activity<input id="newEventName" placeholder="Tournament / game"></label><label>Time<input id="newEventTime" placeholder="9:00 AM"></label></div><button style="margin-top:12px" onclick="addEvent()">+ Add to ${esc(d)}</button></div><div class="card"><h2>Weekly lineup</h2>${WEEKDAYS.slice(1).concat('Sunday').map(x=>`<div class="daybox"><b>${x}</b>${scheduleDay(x).map(eventHTML).join('')||'<p class="mini">No activity</p>'}</div>`).join('')}</div><div class="card"><h2>Baseball workload log</h2><p class="mini">Use this after lessons or practice. The app flags reported pain but does not diagnose injuries.</p><label>Log date<input type="date" id="baseballDate" value="${esc(d)}" onchange="selectedDate=this.value;render()"></label><div class="grid" style="margin-top:10px"><label>Activity<select id="bbActivity"><option>Pitching</option><option>Practice</option><option>Hitting</option><option>Game</option></select></label><label>Pitch count (if known)<input type="number" min="0" id="bbPitches" placeholder="Optional"></label><label>Throwing effort (1–5)<select id="bbEffort"><option value="">Not recorded</option>${[1,2,3,4,5].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Arm discomfort?<select id="bbPain"><option>No</option><option>Yes</option></select></label></div><label style="display:block;margin-top:10px">Notes<textarea id="bbNotes" placeholder="Lesson notes, throwing workload, arm feel..."></textarea></label><button onclick="addBaseballLog()">Save baseball log</button><div style="margin-top:12px">${Object.entries(db.baseball).filter(([date])=>date===d).flatMap(([date,arr])=>arr.map((x,i)=>`<div class="event"><div class="event-body"><b>${esc(x.activity)}</b><small>${esc(date)} · ${x.pitches||'—'} pitches · arm discomfort: ${esc(x.pain)}</small><small>${esc(x.notes||'')}</small></div><button class="small secondary" onclick="removeBaseballLog('${esc(date)}',${i})">✕</button></div>`)).join('')||'<small>No logs for this date.</small>'}</div></div><div class="card"><h2>Edit repeating schedule</h2><p class="mini">Changes are saved locally. The workout program remains Monday, Thursday, and Saturday.</p>${schedule.map(e=>`<div class="event"><div class="event-body"><b>${esc(e.day)} — ${esc(e.name)}</b><small>${esc(e.time)}</small></div><button class="small secondary" onclick="editEvent('${esc(e.id)}')">Edit</button></div>`).join('')}<button class="secondary" onclick="addRecurring()">+ Add repeating activity</button></div>`}
function addEvent(){let name=$('newEventName').value.trim(),time=$('newEventTime').value.trim();if(!name)return toast('Enter an activity name');db.extraEvents.push({id:String(Date.now()),date:selectedDate,name,time});save();render()}
function removeEvent(id){db.extraEvents=db.extraEvents.filter(e=>e.id!==id);save();render()}
function editEvent(id){let e=db.schedule.find(x=>x.id===id);if(!e)return;let name=prompt('Activity',e.name);if(name===null||!name.trim())return;let time=prompt('Time',e.time);if(time===null)return;e.name=name.trim();e.time=time.trim();save();render()}
function addRecurring(){let name=prompt('Repeating activity name');if(!name?.trim())return;let dayName=prompt('Day of week (e.g., Tuesday)','Tuesday');if(!WEEKDAYS.includes(dayName))return toast('Enter a valid weekday');let time=prompt('Time','Flexible');db.schedule.push({id:'custom-'+Date.now(),day:dayName,name:name.trim(),time:time||'Flexible',type:'baseball'});save();render()}
function addBaseballLog(){let d=$('baseballDate').value,entry={activity:$('bbActivity').value,pitches:$('bbPitches').value,effort:$('bbEffort').value,pain:$('bbPain').value,notes:$('bbNotes').value};db.baseball[d]??=[];db.baseball[d].push(entry);save();render();toast('Baseball workload saved')}
function removeBaseballLog(d,i){db.baseball[d].splice(i,1);save();render()}
const BADGES=[['🏁','First Workout','Complete 1 workout',()=>completedCount()>=1],['🔥','Full Week','Complete all 3 workouts in any week',()=>Array.from({length:12},(_,i)=>DAYS.every(d=>finished(i+1,d))).some(Boolean)],['🏅','12-Week Finisher','Complete all 36 workouts',()=>completedCount()===36],['💪','Strength PR','Log a weighted personal best',()=>['Barbell back squat','Barbell front squat','Barbell strict press'].some(n=>best(n)>0)],['⚡','Speed Progress','Improve 10-yard sprint time',()=>testImproved('10-yard sprint')],['🚀','Explosive Progress','Improve a jump measurement',()=>testImproved('Vertical jump')||testImproved('Broad jump')],['🧠','Smart Training','Complete a readiness check',()=>Object.values(db.readiness).some(r=>r.energy&&r.sleep&&r.soreness!==''&&r.soreness!=null)],['🛡️','Recovery Matters','Complete a recovery-week workout',()=>[4,8,12].some(w=>DAYS.some(d=>finished(w,d)))] ];
function testImproved(name){let t=db.tests[name]||{},a=Number(t[1]),b=Number(t[12]||t[6]);if(!a||!b)return false;return ['10-yard sprint','20-yard sprint','5-10-5 shuttle'].includes(name)?b<a:b>a}
function renderProgress(){let done=completedCount();$('app').innerHTML=`<div class="card hero"><span class="pill">YOUR DEVELOPMENT</span><h1>PROGRESS <span class="accent">REPORT</span></h1><p>Celebrate consistency, strength, speed, and movement quality—not just lifting more.</p><div class="grid"><div><small>WORKOUTS</small><div class="metric">${done}/36</div></div><div><small>BADGES EARNED</small><div class="metric">${BADGES.filter(b=>b[3]()).length}/${BADGES.length}</div></div></div></div><div class="card"><h2>Strength trends</h2><label>Exercise<select id="chartLift" onchange="drawChart()">${['Barbell back squat','Barbell front squat','Barbell strict press','Trap bar deadlift','Dumbbell bench press'].map(x=>`<option>${x}</option>`).join('')}</select></label><canvas class="chart" id="liftChart" width="700" height="270" aria-label="Strength progress chart"></canvas><p class="mini">Highest logged weight for completed sets in each week.</p></div><div class="card"><h2>Athletic performance scorecard</h2><p class="mini">Enter baseline, Week 6, and Week 12 results. Lower sprint times and higher jumps indicate improvement.</p><div class="scroll"><table><tr><th>TEST</th><th>W1</th><th>W6</th><th>W12</th><th>CHANGE</th></tr>${tests.map(t=>`<tr><td>${esc(t[0])}<br><small>${esc(t[1])}</small></td>${[1,6,12].map(w=>`<td><input type="number" min="0" step="any" inputmode="decimal" aria-label="${esc(t[0])} week ${w}" value="${esc(db.tests[t[0]]?.[w]??'')}" oninput="setTest('${esc(t[0])}',${w},this.value)"></td>`).join('')}<td id="test-${tests.indexOf(t)}">${testDelta(t)}</td></tr>`).join('')}</table></div></div><div class="card"><h2>Achievements</h2><div class="badge-grid">${BADGES.map(([emoji,title,description,fn])=>`<div class="badge ${fn()?'':'locked'}"><div class="emoji">${emoji}</div><b>${esc(title)}</b><small>${esc(description)}</small>${fn()?'<span class="pill green">UNLOCKED</span>':'<span class="pill gray">LOCKED</span>'}</div>`).join('')}</div></div><div class="card"><h2>Weekly consistency</h2>${Array.from({length:12},(_,i)=>{let n=DAYS.filter(d=>finished(i+1,d)).length;return `<div class="progresslabel"><small>Week ${i+1}</small><b>${n}/3</b></div><div class="bar"><span style="width:${n/3*100}%"></span></div>`}).join('')}</div>`;drawChart()}
function setTest(name,w,v){db.tests[name]??={};db.tests[name][w]=v===''?'':Number(v);save();let t=tests.find(x=>x[0]===name),cell=$('test-'+tests.indexOf(t));if(cell)cell.textContent=testDelta(t)}
function testDelta(t){let obj=db.tests[t[0]]||{},a=Number(obj[1]),b=Number(obj[12]||obj[6]);if(!a||!b)return '—';let delta=b-a;if(t[2]==='lower')return `${delta<0?'↑':delta>0?'↓':'='} ${Math.abs(delta).toFixed(2)} ${t[1]}`;return `${delta>0?'↑':delta<0?'↓':'='} ${Math.abs(delta).toFixed(1)} ${t[1]}`}
function drawChart(){let c=$('liftChart');if(!c)return;let ctx=c.getContext('2d'),name=$('chartLift').value,vals=[];for(let w=1;w<=12;w++){let sets=DAYS.flatMap(d=>session(w,d).items?.[name]?.sets||[]);let a=sets.filter(x=>x.done&&Number(x.weight)>0).map(x=>Number(x.weight));vals.push(a.length?Math.max(...a):null)}ctx.clearRect(0,0,700,270);ctx.fillStyle='#b7bcc8';ctx.font='15px system-ui';ctx.fillText('Highest logged load (lb)',40,25);ctx.strokeStyle='#505663';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(45,42);ctx.lineTo(45,225);ctx.lineTo(678,225);ctx.stroke();let max=Math.max(10,...vals.filter(v=>v!=null))*1.2;let started=false;ctx.strokeStyle='#cbd0d5';ctx.lineWidth=4;ctx.beginPath();vals.forEach((v,i)=>{let x=58+i*54,y=225-(v/max)*165;ctx.fillStyle='#bec2cd';ctx.fillText(i+1,x-4,247);if(v==null){started=false;return}if(!started){ctx.moveTo(x,y);started=true}else ctx.lineTo(x,y)});ctx.stroke();vals.forEach((v,i)=>{if(v==null)return;let x=58+i*54,y=225-(v/max)*165;ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fillStyle='#e0e4e8';ctx.fill();ctx.fillStyle='#fff';ctx.font='13px system-ui';ctx.fillText(String(v),x-9,y-12)});if(!vals.some(v=>v!=null)){ctx.fillStyle='#aeb2bc';ctx.fillText('Log completed strength sets to see progress.',80,145)}}
function profileData(){return db.profile||{name:'JR',team:'',position:'',bats:'',throws:'',number:'',goal:'Build strength, speed and explosiveness',goalWorkouts:3,trainingNotes:''}}
function updateProfile(field,value){let p=db.profile??={...profileData()};p[field]=field==='goalWorkouts'?Math.max(1,Math.min(7,Number(value)||3)):String(value).slice(0,250);save();toast('Profile saved')}
function confirmProfileSave(){save();view='athlete';render();toast('✓ Profile saved successfully')}
function profileEdit(){let p=profileData();$('app').innerHTML=`<div class="card"><button class="secondary small" onclick="view='athlete';render()">← Profile</button><h1>EDIT <span class="accent">ATHLETE</span></h1><p>Changes save automatically when you finish editing a field. Tap Save Profile to return.</p><div class="photo-edit"><div class="profile-avatar">${p.photo?`<img src="${esc(p.photo)}" alt="Current athlete photo">`:esc((p.name||'JR').slice(0,2).toUpperCase())}</div><div><label>Upload profile photo<input type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" onchange="uploadAthletePhoto(event)"></label><button class="secondary small" style="margin-top:9px" onclick="removeAthletePhoto()">Remove photo</button><p class="mini">Photo is resized on this device and saved with JR’s local profile. Avoid photos showing other children.</p></div></div><div class="grid"><label>Display name<input maxlength="40" value="${esc(p.name)}" onchange="updateProfile('name',this.value)"></label><label>Primary position<input maxlength="40" placeholder="e.g. Pitcher" value="${esc(p.position)}" onchange="updateProfile('position',this.value)"></label><label>Jersey number<input maxlength="5" placeholder="Optional" value="${esc(p.number)}" onchange="updateProfile('number',this.value)"></label><label>Bats<select onchange="updateProfile('bats',this.value)">${['','Right','Left','Switch'].map(v=>`<option value="${v}" ${p.bats===v?'selected':''}>${v||'Not set'}</option>`).join('')}</select></label><label>Throws<select onchange="updateProfile('throws',this.value)">${['','Right','Left'].map(v=>`<option value="${v}" ${p.throws===v?'selected':''}>${v||'Not set'}</option>`).join('')}</select></label></div><label style="display:block;margin-top:13px">Training goal<textarea maxlength="250" onchange="updateProfile('goal',this.value)">${esc(p.goal)}</textarea></label><label style="display:block;margin-top:13px">Weekly workout goal<select onchange="updateProfile('goalWorkouts',this.value)">${[1,2,3,4,5,6,7].map(v=>`<option value="${v}" ${Number(p.goalWorkouts)===v?'selected':''}>${v} workout${v===1?'':'s'}</option>`).join('')}</select></label><label style="display:block;margin-top:13px">Training notes<textarea maxlength="250" placeholder="Equipment preferences, reminders…" onchange="updateProfile('trainingNotes',this.value)">${esc(p.trainingNotes||'')}</textarea></label><div class="actionrow" style="margin-top:16px"><button class="wide" onclick="confirmProfileSave()">✓ Save Profile</button></div><div class="notice" style="margin-top:14px">Avoid storing medical information or personal contact details in this profile.</div></div>`}
function removeAthletePhoto(){let p=db.profile??={...profileData()};delete p.photo;save();render();toast('Profile picture removed')}
async function uploadAthletePhoto(ev){const file=ev.target.files?.[0];if(!file)return;if(file.size>15*1024*1024){alert('Choose a photo smaller than 15 MB.');return}try{let bitmap=await createImageBitmap(file),size=256,canvas=document.createElement('canvas');canvas.width=canvas.height=size;let ctx=canvas.getContext('2d');let side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,size,size);bitmap.close?.();let photo=canvas.toDataURL('image/jpeg',.75);if(photo.length>180000)throw Error('Image too large after resizing');let p=db.profile??={...profileData()};p.photo=photo;save();render();toast('Photo updated')}catch(e){alert('Could not process that photo. Try a JPG or PNG. '+e.message)}}
function measurements(){return Array.isArray(db.measurements)?db.measurements:[]}
function latestMeasure(field){return [...measurements()].filter(x=>Number(x[field])>0).sort((a,b)=>a.date.localeCompare(b.date)).at(-1)}
function measurementChart(field,unit){let points=[...measurements()].filter(x=>Number(x[field])>0).sort((a,b)=>a.date.localeCompare(b.date));if(!points.length)return '<p class="mini">No measurements yet. Add an entry to start a chart.</p>';if(points.length===1)return `<div class="metric">${esc(points[0][field])} <small>${unit}</small></div><p class="mini">Add another dated measurement to see a trend.</p>`;let vals=points.map(x=>Number(x[field])),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(max-min,1),xy=vals.map((v,i)=>[(20+i*280/(vals.length-1)).toFixed(1),(140-(v-min)/range*112).toFixed(1)]),line=xy.map(a=>a.join(',')).join(' ');return `<svg class="growth-chart" viewBox="0 0 320 170" role="img" aria-label="${field} trend from ${vals[0]} to ${vals.at(-1)} ${unit}"><line x1="20" y1="140" x2="300" y2="140" stroke="#626a73"/><polyline points="${line}" fill="none" stroke="#e2e6ea" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${xy.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="#f4f5f6"/>`).join('')}<text x="20" y="161" fill="#c8cdd2" font-size="11">${esc(points[0].date)}</text><text x="300" y="161" text-anchor="end" fill="#c8cdd2" font-size="11">${esc(points.at(-1).date)}</text></svg><p class="mini">${vals[0]} → ${vals.at(-1)} ${unit} · ${points.length} measurements</p>`}
function renderGrowth(){let w=latestMeasure('weight'),h=latestMeasure('height'),height=h?Number(h.height):0,feet=Math.floor(height/12),inch=(height%12).toFixed(1).replace(/\.0$/,'');let rows=[...measurements()].sort((a,b)=>b.date.localeCompare(a.date));$('app').innerHTML=`<div class="card hero"><button class="secondary small" onclick="view='athlete';render()">← Profile</button><span class="pill">ATHLETE DEVELOPMENT</span><h1>HEIGHT & WEIGHT</h1><p>Track JR’s growth over time without weight targets or comparisons to other athletes.</p></div><div class="grid"><div class="card"><small>LATEST WEIGHT</small><div class="metric">${w?esc(w.weight)+' <small>lb</small>':'—'}</div><p class="mini">${w?esc(w.date):'Not recorded'}</p></div><div class="card"><small>LATEST HEIGHT</small><div class="metric">${h?`${feet}′ ${inch}″`:'—'}</div><p class="mini">${h?esc(h.date):'Not recorded'}</p></div></div><div class="card" style="margin-top:13px"><h2>Add measurement</h2><form onsubmit="addMeasurement(event)"><div class="grid"><label>Date<input id="measureDate" type="date" required value="${new Date().toLocaleDateString('en-CA')}"></label><label>Weight (lb)<input id="measureWeight" type="number" inputmode="decimal" min="20" max="600" step="0.1" placeholder="Optional"></label><label>Height — feet<input id="measureFeet" type="number" inputmode="numeric" min="2" max="8" step="1" placeholder="Optional"></label><label>Height — inches<input id="measureInches" type="number" inputmode="decimal" min="0" max="11.9" step="0.1" placeholder="Optional"></label></div><button class="wide" type="submit" style="margin-top:14px">+ Save measurement</button></form><p class="mini">Enter weight, height, or both. Measure under similar conditions for useful trends.</p></div><div class="card"><h2>Weight history</h2>${measurementChart('weight','lb')}</div><div class="card"><h2>Height history</h2>${measurementChart('height','in')}</div><div class="card"><h2>Measurement history</h2>${rows.length?rows.map(x=>`<div class="event"><div class="event-body"><b>${esc(x.date)}</b><small>${x.weight?esc(x.weight)+' lb':''}${x.weight&&x.height?' · ':''}${x.height?`${Math.floor(x.height/12)}′ ${(x.height%12).toFixed(1).replace(/\.0$/,'')}″`:''}</small></div><button class="secondary small" aria-label="Delete measurement on ${esc(x.date)}" onclick="deleteMeasurement('${esc(x.id)}')">Delete</button></div>`).join(''):'<p class="mini">No measurements recorded yet.</p>'}</div><div class="notice">Height and weight change naturally during adolescence. These charts are for observing growth, not judging performance or setting weight-loss goals. Profile and measurement data stay on this device unless cloud sync is enabled.</div>`}
function addMeasurement(ev){ev.preventDefault();let date=$('measureDate').value,weight=$('measureWeight').value,ft=$('measureFeet').value,inch=$('measureInches').value;if(!date||(!weight&&ft===''&&inch==='')){alert('Enter a date and at least one measurement.');return}if((ft!==''||inch!=='')&&ft===''){alert('Enter feet when recording height.');return}let w=weight!==''?Number(weight):null,h=ft!==''?Number(ft)*12+Number(inch||0):null;if((w!==null&&(!Number.isFinite(w)||w<20||w>600))||(h!==null&&(!Number.isFinite(h)||h<24||h>107.9))){alert('Check the measurements and try again.');return}db.measurements??=[];db.measurements.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),date,weight:w,height:h});save();render();toast('Measurement saved')}
function deleteMeasurement(id){if(!confirm('Delete this measurement?'))return;db.measurements=measurements().filter(x=>x.id!==id);save();render();toast('Measurement deleted')}
function profileSettings(){let p=profileData();$('app').innerHTML=`<div class="card"><button class="secondary small" onclick="view='athlete';render()">← Profile</button><h1>WORKOUT <span class="accent">SETTINGS</span></h1><label>Default rest timer<select onchange="db.settings.rest=+this.value;save()">${[60,90,120,180].map(v=>`<option value="${v}" ${Number(db.settings.rest)===v?'selected':''}>${v} seconds</option>`).join('')}</select></label><label style="display:flex;gap:10px;align-items:center;margin-top:15px"><input type="checkbox" ${db.settings.autoRest?'checked':''} onchange="db.settings.autoRest=this.checked;save()"> Auto-start rest timer after a set</label><label style="display:block;margin-top:15px">Weekly workout target<select onchange="updateProfile('goalWorkouts',this.value)">${[1,2,3,4,5,6,7].map(v=>`<option ${Number(p.goalWorkouts)===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="notice" style="margin-top:16px">Workout progression is a suggestion, not a requirement. A coach should supervise technique and adjust for pitching workload and recovery.</div></div>`}
function profileMenu(title,desc,iconName,action){return `<button class="profile-menu" onclick="${action}"><span class="profile-menu-icon">${iconName}</span><span class="profile-menu-text"><b>${title}</b><small>${desc}</small></span><span class="profile-chevron">›</span></button>`}
function renderProfile(){if(view==='parent')return renderParent();if(view==='library')return renderLibrary();if(view==='data')return renderData();if(view==='edit')return profileEdit();if(view==='settings')return profileSettings();if(view==='growth')return renderGrowth();let p=profileData(),count=completedCount(),total=36,pct=Math.min(100,Math.round(count/total*100)),current=DAYS.filter(d=>finished(week,d)).length,goal=Math.max(1,Number(p.goalWorkouts)||3),prNames=['Barbell back squat','Barbell front squat','Barbell strict press','Trap bar deadlift'],prs=prNames.filter(n=>best(n)>0),logged=Object.values(db.baseball).flat().length,first=Object.values(db.sessions).filter(x=>x.finished&&x.date).map(x=>x.date).sort()[0];$('app').innerHTML=`<div class="card profile-hero"><div class="profile-head"><div class="profile-avatar" aria-label="JR athlete avatar">${p.photo?`<img src="${esc(p.photo)}" alt="Athlete profile picture">`:esc((p.name||'JR').trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div class="profile-identity"><span class="pill">ATHLETE PROFILE</span><h1>${esc(p.name||'JR')}${p.number?` <span class="profile-number">#${esc(p.number)}</span>`:''}</h1><p>BASEBALL PERFORMANCE ATHLETE</p><div class="profile-tags">${p.position?`<span>${esc(p.position)}</span>`:''}${p.bats?`<span>Bats ${esc(p.bats)}</span>`:''}${p.throws?`<span>Throws ${esc(p.throws)}</span>`:''}</div></div></div><button class="secondary small" onclick="view='edit';render()">✎ Edit athlete profile</button></div><div class="profile-stats"><div class="card profile-stat"><b>${count}</b><small>Workouts</small></div><div class="card profile-stat"><b>${prs.length}</b><small>Lifts tracked</small></div><div class="card profile-stat"><b>${logged}</b><small>Baseball logs</small></div></div><div class="card"><div class="row"><h2>Training journey</h2><span class="pill gray">WEEK ${week} / 12</span></div><div class="progresslabel"><span>12-week program</span><b>${count}/${total} sessions</b></div><div class="bar"><span style="width:${pct}%"></span></div><div class="profile-week"><div><strong>${current} / ${goal}</strong><small>Workouts completed this week</small></div><div><strong>${phase(week)}</strong><small>Current phase</small></div></div><div class="profile-goal"><span>🎯</span><div><b>My training goal</b><p>${esc(p.goal||'Build strength, speed and explosiveness')}</p></div></div><div class="actionrow"><button class="secondary" onclick="nav('progress')">View progress →</button><button class="secondary" onclick="nav('train')">Go to training →</button></div></div><div class="card"><h2>Athlete development</h2><div class="growth-summary"><div><small>WEIGHT</small><b>${latestMeasure('weight')?esc(latestMeasure('weight').weight)+' lb':'—'}</b></div><div><small>HEIGHT</small><b>${latestMeasure('height')?`${Math.floor(latestMeasure('height').height/12)}′ ${(latestMeasure('height').height%12).toFixed(1).replace(/\.0$/,'')}″`:'—'}</b></div></div><button class="wide" onclick="view='growth';render()">+ Add Height or Weight</button><button class="secondary wide" style="margin-top:8px" onclick="view='growth';render()">View measurement history & charts →</button></div><div class="card"><h2>My training</h2>${profileMenu('Height & weight','Measurements, history and growth charts','📏',"view='growth';render()")}${profileMenu('Personal records','Strength history and athletic test results','🏆',"nav('progress')")}${profileMenu('Exercise library','Videos, technique cues and demonstrations','🎥',"view='library';render()")}${profileMenu('Training calendar','Lessons, practices and gym sessions','📅',"nav('schedule')")}</div><div class="card"><h2>Account & preferences</h2>${profileMenu('Edit athlete details','Photo, position, jersey and goals','👤',"view='edit';render()")}${profileMenu('Workout settings','Rest timer and training preferences','⚙️',"view='settings';render()")}${profileMenu('Parent dashboard','Local overview of progress and recovery','👨‍👦',"view='parent';render()")}${profileMenu('Data, backups & cloud','Export, restore and optional parent-managed sync','☁️',"view='data';render()")}</div><div class="profile-footer"><span>⚾ BASEBALL PERFORMANCE</span><span>JR PERFORMANCE • v5.7</span></div><div class="notice">Athlete profiles are stored locally unless a parent configures cloud backup. Stop activity when pain is reported and consult a qualified clinician for persistent or throwing-related pain.</div>`}

// Exercise video center: safe, coach-curated links can be saved locally. Unverified videos are never presented as vetted.
const VIDEO_TECHNIQUE={
'Barbell back squat':['Brace before each rep; keep your feet planted; move through a comfortable range.','Avoid collapsing knees, rounding the back, or grinding reps.'],
'Barbell front squat':['Keep elbows lifted; brace; sit between the hips with control.','Avoid dropping elbows or loading beyond good form.'],
'Barbell strict press':['Brace ribs down; press smoothly; avoid arching your back.','Avoid painful overhead motion, leaning back, or forced reps.'],
'Trap bar deadlift':['Brace; drive through the floor; stand tall without leaning back.','Avoid jerking the weight or rounding the spine.'],
'Romanian deadlift':['Push hips back; keep the bar close; stop before the back rounds.','Avoid turning the hinge into a squat or reaching too low.'],
'Dumbbell Romanian deadlift':['Hinge through the hips; keep dumbbells close; control the lowering.','Avoid rounding the back or forcing depth.'],
'Broad jump':['Swing arms, jump forward, and stick a soft landing.','Avoid stiff landings or repeated maximal attempts when fatigued.'],
'Low box jump':['Jump to a low, stable box; land quietly; step down.','Do not jump off the box or use an unstable surface.'],
'Medicine ball rotational throw':['Rotate through hips and trunk; use a light ball and open space.','Avoid twisting through a painful shoulder or elbow.'],
'10-yard acceleration sprint':['Lean slightly forward; drive arms; accelerate smoothly.','Avoid reaching excessively with the front foot.'],
'20-yard sprint':['Build speed with coordinated arm action and relaxed shoulders.','Avoid sprinting when sore or fatigued.'],
'10-yard reaction sprint':['React to a clear cue, then accelerate under control.','Avoid starting on a slippery or crowded surface.'],
'5-10-5 shuttle':['Lower hips into changes of direction; plant with control.','Avoid twisting the knee while the foot is planted.'],
'Assisted pull-up':['Start from a stable position; pull with control; lower smoothly.','Avoid swinging or shrugging shoulders.'],
'Face pull':['Use light resistance; pull toward upper face with controlled shoulder blades.','Avoid excessive weight or shrugging.'],
'Pallof press':['Brace and press straight ahead without rotating.','Avoid twisting or holding your breath.'],
'Dead bug':['Keep ribs down; extend opposite arm and leg slowly.','Avoid arching the lower back.'],
'Plank':['Keep shoulders, hips and heels aligned; breathe steadily.','Avoid sagging hips or holding your breath.'],
'Side plank':['Stack hips and shoulders; hold a straight line.','Avoid rolling forward or letting hips sag.']};
function videoEntry(name){return db.videoLibrary?.[name]||{}}
function youtubeId(raw){try{let u=new URL(raw);let h=u.hostname.replace(/^www\./,'');if(h==='youtu.be')return /^[\w-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):null;if(['youtube.com','m.youtube.com','youtube-nocookie.com'].includes(h)){let v=u.searchParams.get('v')||u.pathname.match(/^\/(?:shorts|embed|live)\/([\w-]{11})/)?.[1];return /^[\w-]{11}$/.test(v||'')?v:null}}catch(e){}return null}
function illustrationSpec(name,category){
 const n=name.toLowerCase();let motion='hinge',muscles=['core'],secondary=['back'];
 if(/squat|lunge|split squat|step.up|wall sit/.test(n)){motion='squat';muscles=['quads','glutes'];secondary=['core','hamstrings']}
 else if(/deadlift|hinge|good morning/.test(n)){motion='hinge';muscles=['hamstrings','glutes'];secondary=['back','core']}
 else if(/press|push.up|bench/.test(n)){motion='press';muscles=['chest','shoulders','triceps'];secondary=['core']}
 else if(/pull.up|row|pulldown|face pull/.test(n)){motion='pull';muscles=['back','biceps'];secondary=['shoulders']}
 else if(/sprint|shuffle|agility|acceleration|run|high knee|a.skip/.test(n)){motion='run';muscles=['quads','glutes','calves'];secondary=['core','hamstrings']}
 else if(/jump|bound|hop/.test(n)){motion='jump';muscles=['quads','glutes','calves'];secondary=['core']}
 else if(/rotation|throw|slam|chop/.test(n)){motion='rotate';muscles=['core','shoulders'];secondary=['glutes']}
 else if(/plank|pallof|dead bug|bird dog|carry/.test(n)){motion='brace';muscles=['core'];secondary=['shoulders','glutes']}
 else if(/calf/.test(n)){motion='jump';muscles=['calves'];secondary=['quads']}
 else if(/shoulder|external rotation|band pull/.test(n)){motion='pull';muscles=['shoulders'];secondary=['back']}
 else if(category==='Warm-up'){motion='run';muscles=['quads','glutes'];secondary=['core']}
 return {motion,muscles,secondary};
}
