function primaryLiftFrame(p,kind){
 const pt=(a)=>a.join(',');const head=[p.shoulder[0]-2,p.shoulder[1]-30];
 const joint=(a,b,w,col)=>`<path d="M${pt(a)} L${pt(b)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`;
 const mid=(a,b,t)=>[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];
 const foot=[p.ankle[0]+17,p.ankle[1]+1];const upper=mid(p.shoulder,p.hip,.44);
 let drawing=`<ellipse cx="166" cy="336" rx="76" ry="7" fill="#14171c"/>`;
 drawing+=joint(p.hip,p.knee,24,'#ff715e')+joint(p.knee,p.ankle,16,'#b2bac3')+joint(p.ankle,foot,10,'#b2bac3');
 drawing+=joint(p.hip,p.shoulder,35,'#8c97a3')+joint(p.hip,upper,18,'#e7aa9d');
 drawing+=joint(p.shoulder,p.elbow,14,kind==='Barbell strict press'?'#ff715e':'#9ca6b0')+joint(p.elbow,p.hand,11,'#b0b8c0');
 drawing+=`<circle cx="${head[0]}" cy="${head[1]}" r="19" fill="#aab3be" stroke="#d0d6dd" stroke-width="2"/>`;
 if(kind==='Trap bar deadlift'){
  drawing+=`<ellipse cx="${p.bar[0]-22}" cy="${p.bar[1]}" rx="39" ry="19" fill="none" stroke="#d8dce1" stroke-width="5"/>`;
  drawing+=`<circle cx="${p.bar[0]+18}" cy="${p.bar[1]}" r="14" fill="#343a42" stroke="#e5e8ec" stroke-width="4"/>`;
 }else{
  drawing+=`<path d="M${p.bar[0]-78},${p.bar[1]} h156" stroke="#e1e6eb" stroke-width="6" stroke-linecap="round"/>`;
  drawing+=`<circle cx="${p.bar[0]-67}" cy="${p.bar[1]}" r="18" fill="#363d46" stroke="#d0d7df" stroke-width="5"/><circle cx="${p.bar[0]+67}" cy="${p.bar[1]}" r="18" fill="#363d46" stroke="#d0d7df" stroke-width="5"/>`;
 }
 return drawing;
}
function primaryLiftFigure(name){
 const d=PRIMARY_LIFT_POSES[name];if(!d)return '';
 return `<svg class="primary-lift-svg" viewBox="0 0 320 360" role="img" aria-label="Four illustrated phases of ${esc(name)} in a side view">${d.poses.map((pose,i)=>`<g class="lift-pose lift-pose-${i}">${primaryLiftFrame(pose,name)}</g>`).join('')}</svg>`;
}
function anatomyFigure(name,category){
 const spec=illustrationSpec(name,category),hot=new Set(spec.muscles),mid=new Set(spec.secondary);
 const fill=k=>hot.has(k)?'#ff715e':mid.has(k)?'#e7aa9d':'#59616b';
 const area=(k,shape)=>`<g fill="${fill(k)}" stroke="#aeb6be" stroke-width="1.4">${shape}</g>`;
 return `<svg class="anatomy-svg anatomy-${spec.motion}" viewBox="0 0 320 360" role="img" aria-label="Schematic moving figure and highlighted muscle groups for ${esc(name)}">
 <defs><linearGradient id="bodyMetal" x2="1" y2="1"><stop stop-color="#aeb6c0"/><stop offset="1" stop-color="#626c78"/></linearGradient></defs>
 <ellipse cx="160" cy="334" rx="78" ry="9" fill="#171b20"/>
 <g class="figure-motion" stroke-linecap="round" stroke-linejoin="round">
 <g class="legs-motion">${area('quads','<path d="M137 207 L158 210 157 278 145 284 130 266Z"/><path d="M163 210 L183 207 191 266 177 284 164 278Z"/>')}${area('hamstrings','<path d="M130 232 L143 242 146 270 133 260Z"/><path d="M177 242 L190 232 187 260 174 270Z"/>')}${area('calves','<path d="M142 282 L155 282 151 319 143 322Z"/><path d="M166 282 L178 282 176 322 168 319Z"/>')}<path d="M145 318 L143 331 129 332 M176 318 L178 331 192 332" fill="none" stroke="#aeb6c0" stroke-width="9"/></g>
 <g class="torso-motion">${area('glutes','<ellipse cx="146" cy="209" rx="17" ry="14"/><ellipse cx="174" cy="209" rx="17" ry="14"/>')}${area('core','<path d="M145 155 Q160 164 175 155 L180 199 Q160 209 140 199Z"/>')}${area('chest','<path d="M129 139 Q145 128 159 143 L157 161 132 165Z"/><path d="M161 143 Q177 128 191 139 L188 165 163 161Z"/>')}${area('back','<path d="M131 142 Q160 158 189 142 L178 185 142 185Z"/>')}<path d="M130 138 L142 120 178 120 190 138 181 203 139 203Z" fill="none" stroke="#b6bec7" stroke-width="3"/>
 <g class="arms-motion">${area('shoulders','<circle cx="127" cy="142" r="12"/><circle cx="193" cy="142" r="12"/>')}${area('triceps','<path d="M114 153 L125 154 115 192 105 190Z"/><path d="M195 154 L206 153 215 190 205 192Z"/>')}${area('biceps','<path d="M117 154 L126 158 119 186 109 183Z"/><path d="M194 158 L203 154 211 183 201 186Z"/>')}<path d="M110 188 L100 228 M210 188 L220 228" stroke="#9ca6b0" stroke-width="12"/><circle cx="100" cy="233" r="7" fill="#9ca6b0"/><circle cx="220" cy="233" r="7" fill="#9ca6b0"/></g>
 <path d="M153 118 L153 106 167 106 167 118" stroke="#aeb6c0" stroke-width="10"/><ellipse cx="160" cy="80" rx="27" ry="32" fill="url(#bodyMetal)" stroke="#bfc7ce" stroke-width="2"/><path d="M148 79 Q160 86 172 79 M152 93 Q160 97 168 93" fill="none" stroke="#48525e" stroke-width="2"/>
 </g></g></svg>`;
}
function setIllustrationPlaying(playing){let stage=document.getElementById('illustrationStage');if(stage){stage.classList.toggle('paused',!playing);let b=document.getElementById('illustrationToggle');if(b)b.textContent=playing?'Ⅱ Pause':'▶ Play'}}
function showExerciseVideo(name){let e=DAYS.flatMap(d=>exercises[d]).find(e=>e[0]===name);if(!e)return;let [cue,mistake]=VIDEO_TECHNIQUE[name]||[e[5],'Avoid rushing, pain, or loads that compromise controlled technique.'];let saved=videoEntry(name),id=youtubeId(saved.url||''),spec=illustrationSpec(name,e[1]);let old=$('videoOverlay');if(old)old.remove();let overlay=document.createElement('div');overlay.id='videoOverlay';overlay.className='video-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Exercise illustration: '+name);overlay.innerHTML=`<div class="video-sheet"><div class="row"><span class="pill gray">${esc(e[1])} • MOVEMENT GUIDE</span><button class="secondary small" onclick="closeExerciseVideo()" aria-label="Close illustration">✕ Close</button></div><h2>${esc(name)}</h2><div class="illustration-stage" id="illustrationStage">${PRIMARY_LIFT_POSES[name]?primaryLiftFigure(name):anatomyFigure(name,e[1])}<span class="illustration-caption">${PRIMARY_LIFT_POSES[name]?"EXERCISE-SPECIFIC POSE SEQUENCE":"ANIMATED MOVEMENT SCHEMATIC"}</span></div><div class="illustration-actions"><button class="secondary small" id="illustrationToggle" onclick="setIllustrationPlaying(document.getElementById('illustrationStage').classList.contains('paused'))">Ⅱ Pause</button><button class="secondary small" onclick="document.getElementById('illustrationStage').classList.remove('paused');void document.getElementById('illustrationStage').offsetWidth;document.getElementById('illustrationStage').classList.add('replay');setTimeout(()=>document.getElementById('illustrationStage')?.classList.remove('replay'),30)">↻ Replay</button></div><div class="muscle-panel"><b>Muscles emphasized (illustrative)</b><p><span class="muscle-dot primary"></span> Primary: ${esc(spec.muscles.join(', '))}</p><p><span class="muscle-dot secondary"></span> Supporting: ${esc(spec.secondary.join(', '))}</p></div><div class="video-cues"><div><b>✓ Coaching cues</b><p>${esc(cue)}</p></div><div><b>! Common mistakes</b><p>${esc(mistake)}</p></div></div><div class="notice">${PRIMARY_LIFT_POSES[name]?"This sequence illustrates four distinct exercise positions, but is <b>not motion capture or a complete form demonstration</b>.":"This is a simplified animated illustration, <b>not a precise demonstration of joint mechanics</b>."} Review actual form with a qualified coach, especially for loaded lifts.</div><div class="actionrow" style="margin-top:12px"><button class="secondary" onclick="toggleTechniqueReviewed(decodeURIComponent('${encodeURIComponent(name)}'))">${saved.reviewed?'✓ Reviewed':'☐ Mark reviewed'}</button></div><details class="coach-video"><summary>Optional: coach-approved real video</summary>${id?`<div class="video-frame"><iframe src="https://www.youtube-nocookie.com/embed/${id}?rel=0" title="${esc(name)} coach demonstration" loading="lazy" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>`:'<p class="mini">No coach video saved. The illustrated guide above is ready without setup.</p>'}<label class="video-url-label">YouTube video URL<input id="videoUrlInput" type="url" placeholder="Optional YouTube link" value="${esc(saved.url||'')}" oninput="previewExerciseVideo(this.value)"></label><div id="videoPastePreview" class="mini"></div><button onclick="saveExerciseVideo(decodeURIComponent('${encodeURIComponent(name)}'))">Save coach video</button>${saved.url?`<button class="secondary" onclick="removeExerciseVideo(decodeURIComponent('${encodeURIComponent(name)}'))">Remove</button>`:''}</details></div>`;overlay.addEventListener('click',event=>{if(event.target===overlay)closeExerciseVideo()});document.body.appendChild(overlay);overlay.querySelector('button').focus()}

function previewExerciseVideo(raw){let id=youtubeId(raw.trim()),slot=document.getElementById('videoPastePreview');if(!slot)return;slot.textContent=id?'Valid YouTube video — tap Save video to play it above.':'Paste a valid YouTube link to enable the in-app player.'}
function closeExerciseVideo(){document.getElementById('videoOverlay')?.remove()}
function saveExerciseVideo(name){let url=$('videoUrlInput')?.value.trim()||'';if(!youtubeId(url)){toast('Enter a valid YouTube video URL');return}db.videoLibrary??={};db.videoLibrary[name]={...videoEntry(name),url};save();showExerciseVideo(name);toast('✓ Demonstration video saved')}
function removeExerciseVideo(name){db.videoLibrary??={};db.videoLibrary[name]={...videoEntry(name),url:''};save();showExerciseVideo(name);toast('Video removed')}
function toggleTechniqueReviewed(name){db.videoLibrary??={};db.videoLibrary[name]={...videoEntry(name),reviewed:!videoEntry(name).reviewed};save();showExerciseVideo(name);toast('✓ Technique checklist updated')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeExerciseVideo()});
function renderLibrary(){let all=[...new Map(DAYS.flatMap(d=>exercises[d]).map(e=>[e[0],e])).values()];let query=(window.exerciseLibraryQuery||'').toLowerCase(),category=window.exerciseLibraryCategory||'All';let categories=['All',...new Set(all.map(e=>e[1]))];let filtered=all.filter(e=>(category==='All'||e[1]===category)&&(!query||`${e[0]} ${e[1]}`.toLowerCase().includes(query)));$('app').innerHTML=`<div class="card"><span class="pill gray">QUICK REFERENCE</span><h1>MOVEMENT LIBRARY</h1><p>Browse every movement in JR's program. Tap a movement to play its in-app illustrated guide, review muscle groups and technique, or watch a saved coach video. Four primary lifts include exercise-specific position sequences; the others use simplified movement schematics.</p><label>Search exercises<input type="search" placeholder="Search movement or category" value="${esc(window.exerciseLibraryQuery||'')}" oninput="window.exerciseLibraryQuery=this.value;renderLibrary()"></label><div class="video-filter-row">${categories.map(c=>`<button class="small ${category===c?'':'secondary'}" onclick="window.exerciseLibraryCategory='${esc(c)}';renderLibrary()">${esc(c)}</button>`).join('')}</div><p class="mini">${filtered.length} of ${all.length} movements · Illustrated guides available offline</p></div>${filtered.map(e=>`<div class="card video-library-item"><div><span class="pill gray">${esc(e[1])}</span><h3>${esc(e[0])}</h3><p class="mini">${esc(e[5])}</p></div><button class="secondary" onclick="showExerciseVideo(decodeURIComponent('${encodeURIComponent(e[0])}'))">▶ Watch Guide</button></div>`).join('')||'<div class="card">No movements found.</div>'}`}

function renderParent(){let complete=completedCount(),bad=Object.entries(db.readiness).filter(([k,v])=>v.pain==='yes'),logs=Object.values(db.baseball).flat(),weight=Number(db.tests['Body weight']?.[12]||db.tests['Body weight']?.[6]||db.tests['Body weight']?.[1])||null;$('app').innerHTML=`<div class="card hero"><button class="secondary small" onclick="view='athlete';render()">← Profile</button><span class="pill">PARENT OVERVIEW • LOCAL</span><h1>JR'S <span class="accent">DEVELOPMENT</span></h1><p>Review consistency, performance, and reported recovery. This is a view on the same device, not a separate parent login.</p></div><div class="grid"><div class="card"><small>WORKOUTS</small><div class="metric">${complete}/36</div></div><div class="card"><small>BASEBALL LOGS</small><div class="metric">${logs.length}</div></div><div class="card"><small>PAIN FLAGS</small><div class="metric ${bad.length?'accent':'good'}">${bad.length}</div></div><div class="card"><small>BODY WEIGHT</small><div class="metric">${weight??'—'}${weight?' lb':''}</div></div></div><div class="card" style="margin-top:13px"><h2>Readiness & recovery</h2>${bad.length?`<div class="notice danger">Pain was reported in: ${bad.map(([k])=>esc(k)).join(', ')}. Review before training and consult a qualified clinician for persistent pain.</div>`:'<div class="notice good">No pain flags currently recorded. This does not replace direct check-ins.</div>'}<p>Keep strength progress gradual, especially around Tuesday pitching and Thursday hitting.</p></div><div class="card"><h2>Training progress</h2>${DAYS.map(d=>`<div class="event"><div class="event-body"><b>${d}</b><small>${Array.from({length:12},(_,i)=>finished(i+1,d)).filter(Boolean).length}/12 workouts completed</small></div></div>`).join('')}<button class="secondary" onclick="nav('progress')">View performance scorecard</button></div><div class="card"><h2>Baseball workload</h2>${Object.entries(db.baseball).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,8).flatMap(([date,entries])=>entries.map(x=>`<div class="event"><div class="event-body"><b>${esc(date)} — ${esc(x.activity)}</b><small>${x.pitches||'—'} pitches · discomfort: ${esc(x.pain)}</small></div></div>`)).join('')||'<p>No baseball sessions logged yet.</p>'}</div>`}
function renderData(){$('app').innerHTML=`<div class="card"><button class="secondary small" onclick="view='athlete';render()">← Profile</button><h1>DATA & BACKUPS</h1><p>JR's records stay in this browser unless you choose to export or configure cloud synchronization.</p><div class="actionrow"><button onclick="exportBackup()">↓ Backup JSON</button><button class="secondary" onclick="exportCSV()">↓ Workout CSV</button></div><label style="display:block;margin-top:16px">Restore JSON backup<input type="file" accept=".json,application/json" onchange="restoreBackup(event)"></label></div><div class="card"><h2>Optional parent-managed cloud sync</h2><p>Connect your own Supabase project to back up and sync across devices. Setup is required; it is <b>not enabled by default</b>. Use a parent-controlled account for JR.</p><div class="notice">Do not use a Supabase service-role key. Use only a public/publishable (anon) key with the row-level security rules supplied in the setup guide. GitHub Pages remains public, but saved workout data is not uploaded to GitHub.</div><label style="display:block;margin-top:12px">Supabase project URL<input id="cloudUrl" style="width:100%" placeholder="https://PROJECT.supabase.co" value="${esc(db.settings.cloudUrl||'')}"></label><label style="display:block;margin-top:10px">Public / anon key<input id="cloudKey" style="width:100%" placeholder="Public key (never service-role)" value="${esc(db.settings.cloudKey||'')}"></label><button class="secondary" style="margin-top:10px" onclick="saveCloudConfig()">Save connection settings</button><hr class="divider"><label style="display:block">Parent email<input id="cloudEmail" type="email" autocomplete="username" style="width:100%" placeholder="parent@example.com"></label><label style="display:block;margin-top:10px">Password<input id="cloudPassword" type="password" autocomplete="current-password" style="width:100%"></label><div class="actionrow" style="margin-top:12px"><button onclick="cloudLogin()">Sign in</button><button class="secondary" onclick="cloudSignUp()">Create parent account</button></div><p class="mini" id="cloudStatus">${authToken?'Signed in for this session.':'Not signed in.'}</p><div class="actionrow"><button class="secondary" onclick="cloudPush(false)">↑ Upload backup</button><button class="secondary" onclick="cloudPull()">↓ Restore cloud data</button><button class="secondary" onclick="cloudLogout()">Sign out</button></div><label style="display:flex;gap:9px;align-items:center;margin-top:13px"><input type="checkbox" ${db.settings.cloudAuto?'checked':''} onchange="db.settings.cloudAuto=this.checked;save()"> Auto-backup after changes when signed in</label><p class="mini">Cloud restore replaces this device's current data after confirmation. Export a local backup first. A different device must sign in and restore once before auto-backup.</p></div><div class="card"><h2>Erase local records</h2><p>Only do this if you've backed up JR's data. This cannot be undone.</p><button style="background:#545b62" onclick="if(confirm('Permanently erase all local records?')){localStorage.removeItem(KEY);location.reload()}">Delete all local data</button></div>`}
function download(name,contents,type){let url=URL.createObjectURL(new Blob([contents],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function exportBackup(){download('JR_Performance_Backup.json',JSON.stringify(db,null,2),'application/json')}
function exportCSV(){let rows=[['Week','Day','Exercise','Set','Weight (lb)','Reps/result','Done','Workout finished','Date']];for(let w=1;w<=12;w++)for(let d of DAYS){let s=session(w,d);for(let e of exercises[d]){let a=s.items?.[e[0]]?.sets||[];a.forEach((x,i)=>rows.push([w,d,e[0],i+1,x.weight??'',x.reps??'',x.done?'Yes':'No',s.finished?'Yes':'No',s.date||'']))}}download('JR_Performance_Workout_Log.csv',rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv')}
async function restoreBackup(ev){let file=ev.target.files?.[0];if(!file)return;try{let parsed=JSON.parse(await file.text());if(!parsed.sessions||!parsed.tests||typeof parsed.sessions!=='object')throw Error('Not a JR Performance backup');if(!confirm('Replace current local data with this backup? Export a backup first if needed.'))return;db={...structuredClone(base),...parsed,settings:{...base.settings,...parsed.settings}};save();render();toast('Backup restored')}catch(e){alert('Could not restore: '+e.message)}}
function saveCloudConfig(){let url=$('cloudUrl').value.trim().replace(/\/$/,''),key=$('cloudKey').value.trim();if(url&&!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(url))return toast('Enter a valid HTTPS Supabase project URL');db.settings.cloudUrl=url;db.settings.cloudKey=key;save();toast('Connection settings saved locally')}
function cloudConfig(){let url=db.settings.cloudUrl,key=db.settings.cloudKey;if(!url||!key)throw Error('Save your Supabase project URL and public key first.');return{url,key}}
async function cloudAuth(endpoint){try{saveCloudConfig();let {url,key}=cloudConfig(),email=$('cloudEmail').value.trim(),password=$('cloudPassword').value;if(!email||!password)throw Error('Enter email and password');let r=await fetch(`${url}/auth/v1/${endpoint}`,{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({email,password})});let x=await r.json();if(!r.ok)throw Error(x.msg||x.error_description||x.message||'Authentication failed');if(x.access_token){authToken=x.access_token;authUser=x.user?.id;toast('Signed in. You can now sync.')}else toast('Check your email to confirm the account, then sign in.');render()}catch(e){alert(e.message)}}
function cloudLogin(){return cloudAuth('token?grant_type=password')}function cloudSignUp(){return cloudAuth('signup')}
function cloudLogout(){authToken=null;authUser=null;toast('Signed out');render()}
async function cloudRequest(method,path,body){let {url,key}=cloudConfig();if(!authToken||!authUser)throw Error('Sign in with the parent account first');let r=await fetch(url+'/rest/v1/'+path,{method,headers:{apikey:key,Authorization:'Bearer '+authToken,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=representation'},body:body?JSON.stringify(body):undefined});if(!r.ok){let text=await r.text();throw Error('Cloud request failed: '+text.slice(0,220))}return r.json()}
async function cloudPush(silent=false){try{if(!authToken||!authUser){if(!silent)toast('Sign in first');return}let data=structuredClone(db);delete data.settings.cloudKey;delete data.settings.cloudUrl;delete data.settings.cloudAuto;await cloudRequest('POST','jr_backups?on_conflict=user_id',{user_id:authUser,payload:data,updated_at:new Date().toISOString()});if(!silent)toast('Cloud backup uploaded')}catch(e){if(!silent)alert(e.message);else console.warn(e)}}
async function cloudPull(){try{let rows=await cloudRequest('GET','jr_backups?select=payload,updated_at&user_id=eq.'+encodeURIComponent(authUser));if(!rows?.length)return toast('No cloud backup found');if(!confirm('Restore cloud backup from '+rows[0].updated_at+'? This replaces local workout records. Export a local backup first.'))return;let data=rows[0].payload;if(!data?.sessions||!data?.tests)throw Error('Cloud backup format is invalid');let settings={...db.settings};db={...structuredClone(base),...data,settings:{...base.settings,...data.settings,...settings}};save();render();toast('Cloud backup restored')}catch(e){alert(e.message)}}
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);
render();
